cat > /usr/local/libexec/help-site.py <<'PYEOF'
#!/usr/bin/python3
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer

ROOT = "/srv/legacy2/permanent-url-migration"

class HelpHandler(SimpleHTTPRequestHandler):
    def _redirect_legacy(self):
        raw_path, separator, query = self.path.partition("?")
        if raw_path == "/manual" or raw_path.startswith("/manual/"):
            target = "/help" + raw_path[len("/manual"):]
            if separator:
                target += "?" + query
            self.send_response(301)
            self.send_header("Location", target)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return True
        return False

    def do_GET(self):
        if not self._redirect_legacy():
            super().do_GET()

    def do_HEAD(self):
        if not self._redirect_legacy():
            super().do_HEAD()

if __name__ == "__main__":
    server = ThreadingHTTPServer(("0.0.0.0", 8080), lambda *args, **kwargs: HelpHandler(*args, directory=ROOT, **kwargs))
    server.serve_forever()
PYEOF
